export class World {
  constructor(seed = 1337) {
    this.seed = seed >>> 0;
    this.size = WORLD_SIZE;
    this.chunks = new Map();
    this.objects = new Map();
    this.taken = new Map(); // object id -> regrow-at (seconds)
    this.hidden = new Set();
    this.elev = new Float32Array(GRID * GRID);
    this.moist = new Float32Array(GRID * GRID);
    this.temp = new Float32Array(GRID * GRID);
    this.crys = new Float32Array(GRID * GRID);
    this.buildGrids();
    this.palettes = this.buildPalettes();
    this.mapBase = this.buildMapBase();
    this.findSpawn = this.findSpawn.bind(this);
  }

  buildGrids() {
    const s = this.seed;
    for (let gy = 0; gy < GRID; gy++) {
      for (let gx = 0; gx < GRID; gx++) {
        const nx = gx / (GRID - 1);
        const ny = gy / (GRID - 1);
        const wx = nx * this.size;
        const wy = ny * this.size;
        const base = fbm(wx / 1050 + 7.2, wy / 1050 - 3.4, s + 11, 5, 2.02, 0.52);
        const ridge = Math.pow(fbm(wx / 520, wy / 520, s + 71, 4, 2.1, 0.5), 2.1);
        const dx = nx - 0.5;
        const dy = ny - 0.5;
        const fall = smoothstep(clamp((Math.hypot(dx, dy) * 2 - 0.55) / 0.62, 0, 1));
        let e = 0.19 + base * 0.68 + ridge * 0.17 - fall * 0.48;
        // winding river channels carved through the lowlands
        const river = Math.abs(fbm(wx / 470 + 51, wy / 470 - 23, s + 303, 3, 2.0, 0.55) - 0.5);
        if (river < 0.031 && e > 0.3 && e < 0.7) e -= (0.031 - river) * 2.5;
        const m = clamp(0.1 + fbm(wx / 860 + 14, wy / 720 - 8, s + 201, 4, 2.04, 0.5) * 0.78 + (0.48 - e) * 0.34, 0, 1);
        const t = clamp(0.22 + fbm(wx / 1500 + 3, wy / 1500 + 8, s + 337, 3, 2.1, 0.5) * 0.72 - ny * 0.08, 0, 1);
        const cr = fbm(wx / 640 - 6, wy / 640 + 3, s + 555, 3, 2.0, 0.5);
        const i = gy * GRID + gx;
        this.elev[i] = e;
        this.moist[i] = m;
        this.temp[i] = t;
        this.crys[i] = cr;
      }
    }
  }

  sample(arr, x, y) {
    const fx = clamp((x / this.size) * (GRID - 1), 0, GRID - 1.001);
    const fy = clamp((y / this.size) * (GRID - 1), 0, GRID - 1.001);
    const x0 = Math.floor(fx);
    const y0 = Math.floor(fy);
    const tx = fx - x0;
    const ty = fy - y0;
    const i0 = y0 * GRID + x0;
    const i1 = i0 + GRID;
    const a = lerp(arr[i0], arr[i0 + 1], tx);
    const b = lerp(arr[i1], arr[i1 + 1], tx);
    return lerp(a, b, ty);
  }

  elevAt(x, y) { return this.sample(this.elev, x, y); }
  moistAt(x, y) { return this.sample(this.moist, x, y); }
  tempAt(x, y) { return this.sample(this.temp, x, y); }
  crystalAt(x, y) { return this.sample(this.crys, x, y); }
  isWater(x, y) { return this.elevAt(x, y) < WATER; }
  isDeep(x, y) { return this.elevAt(x, y) < DEEP; }

  biomeAt(x, y) {
    const e = this.elevAt(x, y);
    if (e < DEEP) return 'deep';
    if (e < WATER) return 'shallow';
    if (e > 0.755) return 'highland';
    const c = this.crystalAt(x, y);
    if (c > 0.71 && e > 0.41 && this.moistAt(x, y) > 0.44) return 'crystal';
    const t = this.tempAt(x, y);
    const m = this.moistAt(x, y);
    if (t > 0.785 && m < 0.36 && e > 0.43) return 'ash';
    if (e < 0.395) return 'sand';
    if (m > 0.655 && e < 0.5) return 'swamp';
    if (m > 0.6) return 'forest';
    if (m < 0.375) return 'savannah';
    if (e > 0.69) return 'highland';
    return 'meadow';
  }

  buildPalettes() {
    const out = {};
    for (const [key, b] of Object.entries(BIOMES)) {
      const list = [
        b.ground,
        mix(b.ground, b.alt, 0.25),
        mix(b.ground, b.alt, 0.5),
        mix(b.ground, b.alt, 0.78),
        b.alt,
        shade(b.ground, -0.08),
        shade(b.alt, 0.06),
        shade(b.ground, 0.07),
        b.detail
      ];
      out[key] = list;
    }
    return out;
  }

  cellColor(key, x, y) {
    const p = this.palettes[key];
    const n = valueNoise(x / 90, y / 90, this.seed + 31);
    const n2 = valueNoise(x / 23, y / 23, this.seed + 47);
    return p[Math.min(p.length - 1, Math.floor((n * 0.75 + n2 * 0.45) * p.length))];
  }

  getChunk(cx, cy) {
    const key = cx + ',' + cy;
    let c = this.chunks.get(key);
    if (c) return c;
    const canvas = document.createElement('canvas');
    canvas.width = CHUNK;
    canvas.height = CHUNK;
    const ctx = canvas.getContext('2d');
    this.paintChunk(ctx, cx, cy);
    c = { canvas, cx, cy, key };
    this.chunks.set(key, c);
    if (this.chunks.size > 70) {
      const first = this.chunks.keys().next().value;
      this.chunks.delete(first);
    }
    return c;
  }

  paintChunk(ctx, cx, cy) {
    const ox = cx * CHUNK;
    const oy = cy * CHUNK;
    const rng = new RNG((this.seed ^ (cx * 73856093) ^ (cy * 19349663)) >>> 0);
    const cells = 32;
    const step = CHUNK / cells;
    const waterCells = [];

    for (let gy = 0; gy < cells; gy++) {
      for (let gx = 0; gx < cells; gx++) {
        const x = ox + gx * step;
        const y = oy + gy * step;
        const key = this.biomeAt(x + step * 0.5, y + step * 0.5);
        ctx.fillStyle = this.cellColor(key, x, y);
        ctx.fillRect(gx * step, gy * step, step + 1, step + 1);
        if (BIOMES[key].water) waterCells.push([gx, gy, key]);
      }
    }

    // soft blotches to break up the grid
    for (let i = 0; i < 130; i++) {
      const x = rng.range(0, CHUNK);
      const y = rng.range(0, CHUNK);
      const key = this.biomeAt(ox + x, oy + y);
      const b = BIOMES[key];
      ctx.globalAlpha = 0.16;
      ctx.fillStyle = rng.chance(0.5) ? b.alt : b.ground;
      ctx.beginPath();
      ctx.ellipse(x, y, rng.range(10, 42), rng.range(8, 30), rng.range(0, Math.PI), 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    // shoreline foam
    for (const [gx, gy, key] of waterCells) {
      const x = gx * step;
      const y = gy * step;
      const nx = ox + x + step / 2;
      const ny = oy + y + step / 2;
      let touches = false;
      for (let a = 0; a < 8; a++) {
        const ang = (a / 8) * Math.PI * 2;
        if (!this.isWater(nx + Math.cos(ang) * step * 0.9, ny + Math.sin(ang) * step * 0.9)) { touches = true; break; }
      }
      if (touches) {
        ctx.globalAlpha = 0.35 + rng.next() * 0.2;
        ctx.fillStyle = key === 'deep' ? '#2b8490' : '#cfe3cf';
        for (let i = 0; i < 3; i++) {
          ctx.beginPath();
          ctx.ellipse(x + rng.range(0, step), y + rng.range(0, step), rng.range(3, 9), rng.range(2, 5), rng.range(0, 6), 0, Math.PI * 2);
          ctx.fill();
        }
      }
    }
    ctx.globalAlpha = 1;

    // biome-specific texture
    const counts = {
      meadow: 420, forest: 330, savannah: 300, swamp: 300, sand: 170,
      highland: 200, crystal: 170, ash: 210, deep: 70, shallow: 90
    };
    const mainKey = this.biomeAt(ox + CHUNK / 2, oy + CHUNK / 2);
    const count = counts[mainKey] || 200;
    for (let i = 0; i < count; i++) {
      const x = rng.range(0, CHUNK);
      const y = rng.range(0, CHUNK);
      const key = this.biomeAt(ox + x, oy + y);
      const b = BIOMES[key];
      if (b.water) {
        if (rng.chance(0.5)) {
          ctx.globalAlpha = rng.range(0.12, 0.34);
          ctx.strokeStyle = rng.chance(0.5) ? '#7ccfd0' : '#0a2637';
          ctx.lineWidth = rng.range(0.7, 1.6);
          ctx.beginPath();
          const len = rng.range(4, 14);
          ctx.moveTo(x, y);
          ctx.quadraticCurveTo(x + len / 2, y - rng.range(1, 4), x + len, y);
          ctx.stroke();
        } else {
          ctx.globalAlpha = rng.range(0.2, 0.5);
          ctx.fillStyle = '#d6f6f0';
          ctx.fillRect(x, y, rng.range(0.7, 1.8), rng.range(0.7, 1.8));
        }
        continue;
      }
      if (key === 'sand') {
        ctx.globalAlpha = rng.range(0.2, 0.5);
        ctx.fillStyle = rng.chance(0.6) ? b.detail : '#f2e3b8';
        ctx.beginPath();
        ctx.arc(x, y, rng.range(0.5, 1.6), 0, Math.PI * 2);
        ctx.fill();
        continue;
      }
      if (key === 'meadow' || key === 'forest' || key === 'swamp') {
        ctx.globalAlpha = rng.range(0.22, 0.55);
        ctx.strokeStyle = rng.chance(0.55) ? b.detail : shade(b.alt, 0.12);
        ctx.lineWidth = rng.range(0.7, 1.5);
        const len = rng.range(2.5, 7);
        const lean = rng.range(-2, 2);
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.quadraticCurveTo(x + lean * 0.4, y - len * 0.6, x + lean, y - len);
        ctx.stroke();
      } else if (key === 'savannah') {
        if (rng.chance(0.4)) {
          ctx.globalAlpha = rng.range(0.18, 0.4);
          ctx.strokeStyle = b.detail;
          ctx.lineWidth = 0.8;
          ctx.beginPath();
          ctx.moveTo(x, y);
          ctx.lineTo(x + rng.range(-5, 5), y + rng.range(-5, 5));
          ctx.stroke();
        } else {
          ctx.globalAlpha = rng.range(0.25, 0.55);
          ctx.strokeStyle = '#d8bf76';
          ctx.lineWidth = 1;
          ctx.beginPath();
          ctx.moveTo(x, y);
          ctx.lineTo(x + rng.range(-1, 1), y - rng.range(3, 8));
          ctx.stroke();
        }
      } else if (key === 'highland' || key === 'ash') {
        ctx.globalAlpha = rng.range(0.18, 0.42);
        ctx.fillStyle = key === 'ash' && rng.chance(0.16) ? '#ff7a3c' : shade(b.detail, rng.range(-0.1, 0.15));
        ctx.beginPath();
        ctx.arc(x, y, rng.range(0.6, 2.2), 0, Math.PI * 2);
        ctx.fill();
        if (rng.chance(0.25)) {
          ctx.strokeStyle = rgba('#161212', 0.35);
          ctx.lineWidth = 0.8;
          ctx.beginPath();
          ctx.moveTo(x, y);
          ctx.lineTo(x + rng.range(-8, 8), y + rng.range(-8, 8));
          ctx.stroke();
        }
      } else if (key === 'crystal') {
        ctx.globalAlpha = rng.range(0.15, 0.4);
        ctx.fillStyle = rng.chance(0.4) ? '#b58cff' : b.detail;
        ctx.beginPath();
        ctx.arc(x, y, rng.range(0.5, 1.8), 0, Math.PI * 2);
        ctx.fill();
      }
    }

    // flowers and little biome flourishes
    if (mainKey === 'meadow') {
      const flowers = ['#f2d35c', '#e6738f', '#f5f0d8', '#a68cf5'];
      for (let i = 0; i < 34; i++) {
        const x = rng.range(0, CHUNK);
        const y = rng.range(0, CHUNK);
        if (this.isWater(ox + x, oy + y)) continue;
        ctx.globalAlpha = 0.8;
        ctx.fillStyle = rng.pick(flowers);
        ctx.beginPath();
        ctx.arc(x, y, rng.range(1.1, 2.3), 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 0.4;
        ctx.fillStyle = '#3d6b35';
        ctx.fillRect(x - 0.4, y, 0.8, rng.range(2, 4));
      }
    }
    if (mainKey === 'forest' || mainKey === 'swamp') {
      for (let i = 0; i < 18; i++) {
        const x = rng.range(0, CHUNK);
        const y = rng.range(0, CHUNK);
        if (this.isWater(ox + x, oy + y)) continue;
        ctx.globalAlpha = rng.range(0.2, 0.45);
        ctx.fillStyle = rng.chance(0.5) ? '#8a6e36' : '#c1a04a';
        ctx.beginPath();
        ctx.ellipse(x, y, rng.range(2, 5), rng.range(1, 2.4), rng.range(0, 3), 0, Math.PI * 2);
        ctx.fill();
      }
    }
    ctx.globalAlpha = 1;
  }

  getObjects(cx, cy) {
    const key = cx + ',' + cy;
    let list = this.objects.get(key);
    if (list) return list;
    const rng = new RNG((this.seed ^ (cx * 83492791) ^ (cy * 2971215073) ^ 0x5f3759df) >>> 0);
    list = [];
    const ox = cx * CHUNK;
    const oy = cy * CHUNK;
    const centerKey = this.biomeAt(ox + CHUNK / 2, oy + CHUNK / 2);
    let attempts = 34;
    for (let i = 0; i < attempts; i++) {
      const x = ox + rng.range(34, CHUNK - 34);
      const y = oy + rng.range(34, CHUNK - 34);
      const biome = this.biomeAt(x, y);
      const water = this.isWater(x, y);
      const table = this.objectTable(biome, water, centerKey, rng);
      const type = rng.pick(table);
      if (!type) continue;
      if (type === 'obelisk' && rng.chance(0.72)) continue;
      const meta = OBJECT_META[type];
      const obj = {
        id: `${cx}:${cy}:${i}:${type}`,
        type, x, y, cx, cy,
        r: type === 'oak' || type === 'pine' || type === 'willow' || type === 'acacia' ? rng.range(16, 22) : meta.solid,
        variant: rng.chance(0.25) ? 1 : 0,
        seed: rng.next(),
        poison: type === 'mushroom' && rng.chance(0.28)
      };
      if (type === 'lily' && !water) continue;
      list.push(obj);
    }
    this.objects.set(key, list);
    return list;
  }

  objectTable(biome, water, centerKey, rng) {
    if (water) return ['lily', 'lily', 'lily', 'reed', 'driftwood', null, null];
    switch (biome) {
      case 'forest': return ['oak', 'oak', 'pine', 'bush', 'bush', 'mushroom', 'rock', 'reed', null, null];
      case 'meadow': return ['bush', 'bush', 'bush', 'oak', 'rock', 'mushroom', 'reed', null, null];
      case 'savannah': return ['acacia', 'acacia', 'bush', 'rock', 'rock', 'mushroom', null, null];
      case 'swamp': return ['willow', 'willow', 'reed', 'reed', 'mushroom', 'mushroom', 'rock', null];
      case 'highland': return ['rock', 'rock', 'rock', 'pine', 'crystal', null, null];
      case 'crystal': return ['crystal', 'crystal', 'rock', 'crystal', 'obelisk', null];
      case 'ash': return ['rock', 'rock', 'crystal', 'obelisk', null, null];
      case 'sand': return ['driftwood', 'reed', 'rock', 'bush', null, null];
      default: return ['bush', 'rock', 'reed', null];
    }
  }

  isAvailable(obj, time) {
    const until = this.taken.get(obj.id);
    return !until || until <= time;
  }

  markHarvested(obj, time) {
    const meta = OBJECT_META[obj.type];
    const until = meta.regrow === Infinity ? Infinity : time + meta.regrow;
    this.taken.set(obj.id, until);
    return meta;
  }

  harvestInfo(obj) {
    return OBJECT_META[obj.type];
  }

  nearbyObjects(x, y, radius) {
    const minx = Math.floor((x - radius) / CHUNK);
    const maxx = Math.floor((x + radius) / CHUNK);
    const miny = Math.floor((y - radius) / CHUNK);
    const maxy = Math.floor((y + radius) / CHUNK);
    const out = [];
    for (let cy = miny; cy <= maxy; cy++) {
      for (let cx = minx; cx <= maxx; cx++) {
        if (cx < 0 || cy < 0 || cx * CHUNK > this.size || cy * CHUNK > this.size) continue;
        for (const obj of this.getObjects(cx, cy)) {
          if (this.hidden.has(obj.id)) continue;
          if (dist(x, y, obj.x, obj.y) <= radius + obj.r) out.push(obj);
        }
      }
    }
    return out;
  }

  clearArea(x, y, radius) {
    for (const obj of this.nearbyObjects(x, y, radius)) {
      if (obj.type === 'obelisk') continue;
      this.hidden.add(obj.id);
    }
  }

  resolveCollision(x, y, radius) {
    const objs = this.nearbyObjects(x, y, radius + 30);
    let nx = x;
    let ny = y;
    for (const obj of objs) {
      const meta = OBJECT_META[obj.type];
      if (!meta.solid) continue;
      const rr = meta.solid + radius;
      const dx = nx - obj.x;
      const dy = ny - obj.y;
      const d = Math.hypot(dx, dy);
      if (d < rr && d > 0.001) {
        nx = obj.x + (dx / d) * rr;
        ny = obj.y + (dy / d) * rr;
      }
    }
    return { x: nx, y: ny };
  }

  drawGround(ctx, rect) {
    const minx = Math.floor(rect.x / CHUNK);
    const maxx = Math.floor((rect.x + rect.w) / CHUNK);
    const miny = Math.floor(rect.y / CHUNK);
    const maxy = Math.floor((rect.y + rect.h) / CHUNK);
    for (let cy = miny; cy <= maxy; cy++) {
      for (let cx = minx; cx <= maxx; cx++) {
        if (cx < 0 || cy < 0 || cx * CHUNK >= this.size || cy * CHUNK >= this.size) continue;
        const c = this.getChunk(cx, cy);
        ctx.drawImage(c.canvas, cx * CHUNK, cy * CHUNK);
      }
    }
  }

  drawObject(ctx, obj, time) {
    const available = this.isAvailable(obj, time);
    switch (obj.type) {
      case 'oak': this.drawOak(ctx, obj, time, available, 'oak'); break;
      case 'pine': this.drawPine(ctx, obj, time, available); break;
      case 'willow': this.drawWillow(ctx, obj, time, available); break;
      case 'acacia': this.drawAcacia(ctx, obj, time, available); break;
      case 'bush': this.drawBush(ctx, obj, available); break;
      case 'mushroom': this.drawMushroom(ctx, obj, available); break;
      case 'rock': this.drawRock(ctx, obj, available); break;
      case 'reed': this.drawReed(ctx, obj, time, available); break;
      case 'crystal': this.drawCrystal(ctx, obj, time, available); break;
      case 'driftwood': this.drawDriftwood(ctx, obj, available); break;
      case 'obelisk': this.drawObelisk(ctx, obj, time, available); break;
      case 'lily': this.drawLily(ctx, obj, time); break;
      default: break;
    }
  }

  drawShadow(ctx, x, y, rx, ry, a = 0.18) {
    ctx.fillStyle = `rgba(8,20,16,${a})`;
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
    ctx.fill();
  }

  drawOak(ctx, obj, time, available, kind) {
    const { x, y, seed } = obj;
    const sway = Math.sin(time * 0.85 + seed * 19) * 2.2;
    this.drawShadow(ctx, x + 5, y + 3, 28, 11, 0.2);
    if (!available) {
      ctx.fillStyle = '#4c3422';
      ctx.fillRect(x - 5, y - 11, 10, 11);
      ctx.fillStyle = '#8a6640';
      ctx.beginPath(); ctx.ellipse(x, y - 11, 6, 2.5, 0, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = '#b99060'; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.arc(x, y - 11, 3.5, 0, Math.PI * 2); ctx.stroke();
      return;
    }
    ctx.fillStyle = '#5e3f28';
    ctx.beginPath();
    ctx.moveTo(x - 6, y);
    ctx.quadraticCurveTo(x - 3, y - 20, x - 2, y - 31);
    ctx.lineTo(x + 3, y - 31);
    ctx.quadraticCurveTo(x + 3, y - 19, x + 7, y);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = 'rgba(210,170,110,.28)';
    ctx.fillRect(x - 4, y - 27, 2, 25);
    const cx = x + sway;
    const cy = y - 40;
    const blobs = [
      [-19, 6, 17, '#244d2c'], [16, 4, 16, '#2a5630'], [-4, -8, 20, '#336737'],
      [10, -14, 15, '#3f7a40'], [-12, -17, 14, '#2f6234'], [0, 5, 20, '#386f3c']
    ];
    for (const [bx, by, br, col] of blobs) {
      ctx.fillStyle = col;
      ctx.beginPath(); ctx.arc(cx + bx, cy + by, br, 0, Math.PI * 2); ctx.fill();
    }
    ctx.globalAlpha = 0.55;
    ctx.fillStyle = '#62a052';
    for (let i = 0; i < 18; i++) {
      const a = seed * 30 + i * 2.7;
      const rr = 8 + ((i * 7 + seed * 13) % 17);
      ctx.beginPath();
      ctx.arc(cx + Math.cos(a) * rr, cy - 4 + Math.sin(a) * rr * 0.7, 2.6, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
    if (obj.variant) {
      ctx.fillStyle = '#e05252';
      for (let i = 0; i < 5; i++) {
        const a = seed * 12 + i * 1.7;
        ctx.beginPath(); ctx.arc(cx + Math.cos(a) * 16, cy + Math.sin(a) * 11, 2.1, 0, Math.PI * 2); ctx.fill();
      }
    }
  }

  drawPine(ctx, obj, time, available) {
    const { x, y, seed } = obj;
    const sway = Math.sin(time * 0.7 + seed * 11) * 1.6;
    this.drawShadow(ctx, x + 5, y + 2, 22, 9, 0.22);
    if (!available) {
      ctx.fillStyle = '#4a3220';
      ctx.fillRect(x - 4, y - 10, 8, 10);
      return;
    }
    ctx.fillStyle = '#4a3220';
    ctx.fillRect(x - 4, y - 20, 8, 20);
    ctx.fillStyle = '#7a5531';
    ctx.fillRect(x - 2, y - 19, 2, 18);
    const tiers = 4;
    for (let i = 0; i < tiers; i++) {
      const yy = y - 18 - i * 13;
      const w = 26 - i * 5;
      ctx.fillStyle = i % 2 ? '#244e33' : '#2c5b3a';
      ctx.beginPath();
      ctx.moveTo(x - w + sway, yy);
      ctx.lineTo(x + sway, yy - 22);
      ctx.lineTo(x + w + sway, yy);
      ctx.lineTo(x + w * 0.42 + sway, yy - 3);
      ctx.lineTo(x - w * 0.42 + sway, yy - 3);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = 'rgba(140,190,120,.16)';
      ctx.beginPath();
      ctx.moveTo(x + sway, yy - 20);
      ctx.lineTo(x + w * 0.65 + sway, yy - 2);
      ctx.lineTo(x + sway, yy - 5);
      ctx.closePath();
      ctx.fill();
    }
  }

  drawWillow(ctx, obj, time, available) {
    const { x, y, seed } = obj;
    const sway = Math.sin(time * 0.6 + seed * 17) * 2.5;
    this.drawShadow(ctx, x + 6, y + 3, 30, 12, 0.2);
    if (!available) {
      ctx.fillStyle = '#4d3a28'; ctx.fillRect(x - 5, y - 12, 10, 12); return;
    }
    ctx.strokeStyle = '#58452e';
    ctx.lineWidth = 6;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.quadraticCurveTo(x - 4, y - 24, x - 2, y - 38);
    ctx.stroke();
    ctx.strokeStyle = '#6e5637';
    ctx.lineWidth = 1.6;
    ctx.beginPath(); ctx.moveTo(x - 2, y - 32); ctx.lineTo(x - 18 + sway, y - 44); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(x - 1, y - 36); ctx.lineTo(x + 19 + sway, y - 47); ctx.stroke();
    const green = ['#4f7a44', '#5c8a4b', '#3f6b3d'];
    for (let i = 0; i < 30; i++) {
      const a = seed * 15 + i * 1.31;
      const bx = x + Math.cos(a) * (12 + (i % 5) * 6) + sway;
      const by = y - 42 + Math.sin(a) * 7;
      ctx.strokeStyle = green[i % 3];
      ctx.globalAlpha = 0.62;
      ctx.lineWidth = 1.4;
      ctx.beginPath();
      ctx.moveTo(bx, by);
      ctx.quadraticCurveTo(bx + Math.sin(time + i) * 2, by + 10, bx + Math.sin(time * 0.8 + i) * 4, by + 22 + (i % 4) * 3);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
  }

  drawAcacia(ctx, obj, time, available) {
    const { x, y, seed } = obj;
    const sway = Math.sin(time * 0.75 + seed * 13) * 1.5;
    this.drawShadow(ctx, x + 8, y + 4, 34, 11, 0.17);
    if (!available) {
      ctx.fillStyle = '#5b4229'; ctx.fillRect(x - 4, y - 12, 8, 12); return;
    }
    ctx.strokeStyle = '#5b4229';
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.quadraticCurveTo(x - 2, y - 22, x + 1, y - 36);
    ctx.stroke();
    ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(x, y - 33); ctx.lineTo(x - 21, y - 44); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(x, y - 35); ctx.lineTo(x + 23, y - 45); ctx.stroke();
    ctx.fillStyle = '#61773a';
    ctx.beginPath(); ctx.ellipse(x + sway, y - 48, 37, 11, -0.05, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#788f45';
    ctx.beginPath(); ctx.ellipse(x + sway - 4, y - 51, 28, 7, -0.04, 0, Math.PI * 2); ctx.fill();
    ctx.globalAlpha = 0.5;
    ctx.fillStyle = '#a3b866';
    for (let i = 0; i < 12; i++) {
      const a = seed * 20 + i * 2.1;
      ctx.beginPath();
      ctx.arc(x + sway + Math.cos(a) * (10 + (i % 5) * 5), y - 49 + Math.sin(a) * 5, 1.8, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  drawBush(ctx, obj, available) {
    const { x, y, seed } = obj;
    this.drawShadow(ctx, x + 3, y + 2, 18, 7, 0.16);
    const cols = obj.variant ? ['#315c36', '#3d6e3d', '#4f8346'] : ['#2f5d34', '#3c6f3c', '#518346'];
    for (let i = 0; i < 3; i++) {
      const bx = x + Math.cos(seed * 20 + i * 2.1) * 9;
      const by = y - 6 + Math.sin(seed * 17 + i * 1.7) * 4;
      ctx.fillStyle = cols[i];
      ctx.beginPath(); ctx.arc(bx, by, 10 - i * 1.4, 0, Math.PI * 2); ctx.fill();
    }
    if (available) {
      const berry = obj.variant ? '#5b7fd4' : '#d94d5c';
      ctx.fillStyle = berry;
      for (let i = 0; i < 6; i++) {
        const a = seed * 33 + i * 1.9;
        ctx.beginPath();
        ctx.arc(x + Math.cos(a) * 11, y - 7 + Math.sin(a) * 7, 1.8, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.fillStyle = 'rgba(255,255,255,.35)';
      ctx.beginPath(); ctx.arc(x - 9, y - 13, 1, 0, Math.PI * 2); ctx.fill();
    } else {
      ctx.strokeStyle = '#5d4a31';
      ctx.lineWidth = 1.3;
      ctx.beginPath(); ctx.moveTo(x - 5, y); ctx.lineTo(x - 2, y - 9); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(x + 4, y); ctx.lineTo(x + 1, y - 8); ctx.stroke();
    }
  }

  drawMushroom(ctx, obj, available) {
    const { x, y, seed } = obj;
    this.drawShadow(ctx, x + 2, y + 1, 11, 4, 0.15);
    if (!available) {
      ctx.strokeStyle = '#c9b48e';
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + 1, y - 4); ctx.stroke();
      return;
    }
    const capW = 9 + (seed % 5);
    ctx.fillStyle = '#e7dcc2';
    ctx.fillRect(x - 1.5, y - 9, 3, 9);
    ctx.fillStyle = obj.poison ? '#b8404e' : '#9a7a4e';
    ctx.beginPath();
    ctx.ellipse(x, y - 10, capW, capW * 0.55, 0, Math.PI, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = obj.poison ? '#ffd4d8' : '#c8a96e';
    for (let i = 0; i < 4; i++) {
      const a = seed * 10 + i * 1.7;
      ctx.beginPath(); ctx.arc(x + Math.cos(a) * capW * 0.5, y - 11 + Math.sin(a) * 2.4, 1.1, 0, Math.PI * 2); ctx.fill();
    }
  }

  drawRock(ctx, obj, available) {
    const { x, y, seed } = obj;
    this.drawShadow(ctx, x + 3, y + 3, 21, 9, 0.2);
    const s = 15 + (seed % 8);
    if (!available) {
      ctx.fillStyle = '#6e6a62';
      ctx.beginPath(); ctx.ellipse(x, y - 2, 12, 5, 0, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#8f8a80';
      ctx.beginPath(); ctx.ellipse(x - 3, y - 4, 7, 3, 0, 0, Math.PI * 2); ctx.fill();
      return;
    }
    ctx.fillStyle = '#65615a';
    ctx.beginPath();
    ctx.moveTo(x - s, y + 2);
    ctx.lineTo(x - s * 0.65, y - s * 0.7);
    ctx.lineTo(x + s * 0.1, y - s);
    ctx.lineTo(x + s * 0.8, y - s * 0.45);
    ctx.lineTo(x + s, y + 2);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#8a857b';
    ctx.beginPath();
    ctx.moveTo(x - s * 0.6, y - s * 0.62);
    ctx.lineTo(x + s * 0.08, y - s * 0.9);
    ctx.lineTo(x + s * 0.45, y - s * 0.35);
    ctx.lineTo(x - s * 0.25, y - s * 0.2);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = 'rgba(210,204,188,.35)';
    ctx.beginPath();
    ctx.moveTo(x + s * 0.1, y - s * 0.82);
    ctx.lineTo(x + s * 0.36, y - s * 0.4);
    ctx.lineTo(x + s * 0.06, y - s * 0.32);
    ctx.closePath();
    ctx.fill();
    if (seed % 3 < 1) {
      ctx.fillStyle = '#6d8c4d';
      ctx.beginPath(); ctx.arc(x - s * 0.35, y - s * 0.55, 3, 0, Math.PI * 2); ctx.fill();
    }
  }

  drawReed(ctx, obj, time, available) {
    const { x, y, seed } = obj;
    if (!available) {
      ctx.strokeStyle = '#6a6535';
      ctx.lineWidth = 1.4;
      for (let i = 0; i < 3; i++) {
        ctx.beginPath(); ctx.moveTo(x + i * 3 - 3, y); ctx.lineTo(x + i * 3 - 3, y - 5); ctx.stroke();
      }
      return;
    }
    for (let i = 0; i < 7; i++) {
      const a = seed * 21 + i * 1.13;
      const h = 12 + (i % 4) * 4;
      const sway = Math.sin(time * 1.1 + i + seed * 8) * 2;
      ctx.strokeStyle = i % 3 ? '#7f8c47' : '#a3a75c';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(x + Math.cos(a) * 6, y);
      ctx.quadraticCurveTo(x + Math.cos(a) * 7 + sway, y - h * 0.6, x + Math.cos(a) * 5 + sway * 1.5, y - h);
      ctx.stroke();
      if (i % 3 === 0) {
        ctx.fillStyle = '#b4a35d';
        ctx.beginPath(); ctx.ellipse(x + Math.cos(a) * 5 + sway * 1.5, y - h, 1.6, 4, 0.2, 0, Math.PI * 2); ctx.fill();
      }
    }
  }

  drawCrystal(ctx, obj, time, available) {
    const { x, y, seed } = obj;
    if (!available) {
      ctx.fillStyle = '#4b3d68';
      ctx.beginPath(); ctx.moveTo(x - 6, y); ctx.lineTo(x, y - 5); ctx.lineTo(x + 6, y); ctx.closePath(); ctx.fill();
      return;
    }
    const pulse = 0.7 + Math.sin(time * 1.7 + seed * 8) * 0.3;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createRadialGradient(x, y - 16, 2, x, y - 16, 34);
    g.addColorStop(0, `rgba(160,110,255,${0.24 * pulse})`);
    g.addColorStop(1, 'rgba(120,80,220,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(x, y - 16, 34, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
    this.drawShadow(ctx, x + 2, y + 2, 15, 5, 0.18);
    const shards = 4;
    for (let i = 0; i < shards; i++) {
      const bx = x + (i - 1.5) * 6;
      const h = 13 + ((i * 7 + seed * 11) % 16);
      ctx.fillStyle = i % 2 ? '#8a6ed0' : '#b08cff';
      ctx.beginPath();
      ctx.moveTo(bx - 3, y);
      ctx.lineTo(bx + 1, y - h);
      ctx.lineTo(bx + 4, y);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = 'rgba(235,220,255,.55)';
      ctx.beginPath();
      ctx.moveTo(bx + 0.5, y - h + 2);
      ctx.lineTo(bx + 1.8, y - 3);
      ctx.lineTo(bx, y - 2);
      ctx.closePath();
      ctx.fill();
    }
  }

  drawDriftwood(ctx, obj, available) {
    const { x, y, seed } = obj;
    this.drawShadow(ctx, x + 3, y + 2, 18, 5, 0.16);
    ctx.save();
    ctx.translate(x, y - 3);
    ctx.rotate(seed * 4 - 2);
    ctx.fillStyle = available ? '#786146' : '#5c4c39';
    ctx.beginPath(); ctx.ellipse(0, 0, 17, 5.5, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#9b805d';
    ctx.beginPath(); ctx.ellipse(-2, -1.5, 13, 3, 0, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = '#5a4630';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(-14, 0); ctx.lineTo(12, 1); ctx.stroke();
    if (available) {
      ctx.fillStyle = '#8e9f59';
      ctx.beginPath(); ctx.arc(5, -3, 2.2, 0, Math.PI * 2); ctx.fill();
    }
    ctx.restore();
  }

  drawObelisk(ctx, obj, time, available) {
    const { x, y, seed } = obj;
    this.drawShadow(ctx, x + 4, y + 2, 19, 7, 0.24);
    ctx.fillStyle = '#4b4a5b';
    ctx.beginPath();
    ctx.moveTo(x - 10, y);
    ctx.lineTo(x - 7, y - 48);
    ctx.lineTo(x + 7, y - 54);
    ctx.lineTo(x + 10, y);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#626176';
    ctx.beginPath();
    ctx.moveTo(x - 7, y - 3);
    ctx.lineTo(x - 4, y - 46);
    ctx.lineTo(x + 1, y - 50);
    ctx.lineTo(x + 2, y - 3);
    ctx.closePath();
    ctx.fill();
    const glow = available ? 0.55 + Math.sin(time * 1.3 + seed * 8) * 0.35 : 0.1;
    ctx.strokeStyle = `rgba(140,240,210,${glow})`;
    ctx.lineWidth = 1.4;
    for (let i = 0; i < 5; i++) {
      const yy = y - 10 - i * 8;
      ctx.beginPath();
      ctx.moveTo(x - 3, yy);
      ctx.lineTo(x + 1, yy - 3);
      ctx.lineTo(x + 3, yy);
      ctx.lineTo(x - 1, yy - 5);
      ctx.stroke();
    }
    ctx.fillStyle = `rgba(140,240,210,${glow * 0.25})`;
    ctx.beginPath(); ctx.arc(x, y - 28, 19, 0, Math.PI * 2); ctx.fill();
  }

  drawLily(ctx, obj, time) {
    const { x, y, seed } = obj;
    const bob = Math.sin(time * 1.2 + seed * 9) * 1.2;
    ctx.fillStyle = '#3f7c4a';
    ctx.beginPath();
    ctx.ellipse(x, y + bob, 10, 5.5, seed * 3, 0.3, Math.PI * 2 - 0.3);
    ctx.lineTo(x, y + bob);
    ctx.fill();
    ctx.strokeStyle = 'rgba(160,210,150,.5)';
    ctx.lineWidth = 0.8;
    ctx.beginPath(); ctx.moveTo(x, y + bob); ctx.lineTo(x + 7, y + bob - 2); ctx.stroke();
    if (seed > 0.72) {
      ctx.fillStyle = '#f3b8d4';
      for (let i = 0; i < 5; i++) {
        const a = (i / 5) * Math.PI * 2 + seed;
        ctx.beginPath();
        ctx.ellipse(x + Math.cos(a) * 3, y + bob + Math.sin(a) * 2, 2.8, 1.6, a, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.fillStyle = '#ffe37a';
      ctx.beginPath(); ctx.arc(x, y + bob, 1.6, 0, Math.PI * 2); ctx.fill();
    }
  }

  buildMapBase() {
    const c = document.createElement('canvas');
    c.width = MAPRES;
    c.height = MAPRES;
    const ctx = c.getContext('2d');
    for (let y = 0; y < MAPRES; y++) {
      for (let x = 0; x < MAPRES; x++) {
        const wx = (x + 0.5) / MAPRES * this.size;
        const wy = (y + 0.5) / MAPRES * this.size;
        const key = this.biomeAt(wx, wy);
        const b = BIOMES[key];
        const n = valueNoise(wx / 170, wy / 170, this.seed + 99);
        ctx.fillStyle = shade(b.map, (n - 0.5) * 0.16);
        ctx.fillRect(x, y, 1, 1);
      }
    }
    return c;
  }

  findSpawn() {
    // Search for a beautiful, playable starting spot: meadow near water and woodland.
    let best = null;
    let bestScore = -Infinity;
    const R = new RNG(this.seed + 777);
    for (let i = 0; i < 320; i++) {
      const ang = R.range(0, Math.PI * 2);
      const rad = Math.sqrt(R.next()) * this.size * 0.34;
      const x = this.size / 2 + Math.cos(ang) * rad;
      const y = this.size / 2 + Math.sin(ang) * rad;
      const key = this.biomeAt(x, y);
      if (key !== 'meadow' && key !== 'sand' && key !== 'forest') continue;
      if (this.isWater(x, y)) continue;
      let water = 0;
      let forest = 0;
      for (let k = 0; k < 16; k++) {
        const a = (k / 16) * Math.PI * 2;
        const kk = this.biomeAt(x + Math.cos(a) * 280, y + Math.sin(a) * 280);
        if (BIOMES[kk].water) water++;
        if (kk === 'forest') forest++;
      }
      const score = (key === 'meadow' ? 3 : key === 'forest' ? 2 : 1) + water * 0.55 + forest * 0.35;
      if (score > bestScore) { bestScore = score; best = { x, y, key }; }
    }
    if (!best) best = { x: this.size / 2, y: this.size / 2 };
    return best;
  }
}

// Procedural creature anatomy and rendering.
import { hsl, shade, rgba, clamp } from './util.js';
import { STAGES } from './data.js';

const DEFAULT = {
  len: 48, wid: 24, head: 16, legLen: 15, legs: 4,
  tail: 20, tailType: 'taper', spikes: 0, horns: 0, ears: 0,
  fin: 0, wing: 0, eyes: 2, pattern: 'spots', patternColor: '#2a4d33',
  color1: '#63c98a', color2: '#2d5f45', color3: '#b8f0c9',
  eye: '#ffe37a', glow: null, armor: 0, claws: 0, scale: 1,
  pupil: '#1a211c', teeth: 0
};

export function makePlayerPheno(genes, stage, hue, seed = 0) {
  const g = (id) => genes[id] || 0;
  const scale = STAGES[stage - 1].scale * (1 + g('might') * 0.12);
  const base = {
    ...DEFAULT,
    len: 50 * scale,
    wid: 25 * scale,
    head: 17 * scale,
    legLen: 16 * scale,
    tail: (18 + g('swift') * 2 + g('wings') * 2) * scale,
    legs: 4,
    color1: hsl(hue, 56, 55),
    color2: hsl(hue, 50, 33),
    color3: hsl((hue + 24) % 360, 62, 74),
    patternColor: hsl((hue + 320) % 360, 52, 32),
    eye: g('nightvision') ? '#bffcff' : '#ffe37a',
    glow: g('biolum') ? hsl((hue + 80) % 360, 95, 68) : g('electric') ? '#8fd6ff' : g('venom') ? '#8aff6a' : null,
    pattern: ['spots', 'stripes', 'spots', 'none'][seed % 4],
    spikes: g('spikes') * 2 + (stage >= 4 ? 2 : 0),
    horns: g('might') + (stage >= 3 ? 1 : 0),
    fin: g('gills') ? 1 : 0,
    wing: g('wings'),
    armor: g('carapace'),
    claws: g('claws'),
    teeth: g('claws') > 0 ? 1 : 0,
    scale
  };
  if (g('venom')) base.patternColor = '#4d7a2b';
  return base;
}

export function makeSpeciesPheno(species, extraScale = 1) {
  const p = { ...DEFAULT, ...species.pheno };
  const s = (species.size || 1) * extraScale;
  const out = { ...p };
  out.len = (p.len || 40) * s;
  out.wid = (p.wid || 20) * s;
  out.head = (p.head || 14) * s;
  out.legLen = (p.legLen || 12) * s;
  out.tail = (p.tail || 0) * s;
  out.scale = s;
  return out;
}

export function makeHeirPheno(genes, stage, hue, seed = 1) {
  return makePlayerPheno(genes, Math.max(1, stage - 1), hue, seed);
}

function bodyPath(ctx, len, wid) {
  ctx.beginPath();
  ctx.ellipse(0, 0, len * 0.5, wid * 0.5, 0, 0, Math.PI * 2);
}

export function drawCreature(ctx, x, y, angle, p, time, opts = {}) {
  const moving = opts.moving ? 1 : 0;
  const phase = opts.phase || 0;
  const len = p.len;
  const wid = p.wid;
  const head = p.head;
  const legLen = p.legLen;

  // ground shadow (unrotated)
  ctx.save();
  ctx.translate(x, y);
  ctx.fillStyle = 'rgba(8,18,14,0.22)';
  ctx.beginPath();
  ctx.ellipse(3, 6, len * 0.48, wid * 0.38, angle, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  ctx.save();
  ctx.translate(x, y);

  if (opts.selected) {
    ctx.strokeStyle = 'rgba(150,255,200,.35)';
    ctx.lineWidth = 1.2;
    ctx.setLineDash([6, 7]);
    ctx.beginPath();
    ctx.ellipse(0, 0, len * 0.72, wid * 0.9, 0, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  ctx.rotate(angle);
  const walk = time * (moving ? 12 : 2.2) + phase;
  const bob = moving ? Math.sin(walk * 2) * 1.1 : Math.sin(walk) * 0.35;
  ctx.translate(0, bob);

  // wings (under body)
  if (p.wing) {
    const flap = Math.sin(time * 6 + phase) * 0.22 * (moving ? 1 : 0.4);
    for (const side of [-1, 1]) {
      ctx.save();
      ctx.scale(1, side);
      ctx.rotate(flap * side);
      const wg = ctx.createLinearGradient(0, -wid * 0.3, 0, -wid * 1.35);
      wg.addColorStop(0, rgba('#d8fff0', 0.24));
      wg.addColorStop(1, rgba('#9fe0cf', 0.08));
      ctx.fillStyle = wg;
      ctx.strokeStyle = rgba('#c8ffee', 0.32);
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(-len * 0.18, -wid * 0.22);
      ctx.quadraticCurveTo(-len * 0.15, -wid * (0.95 + p.wing * 0.16), len * 0.1, -wid * (1.08 + p.wing * 0.18));
      ctx.quadraticCurveTo(len * 0.24, -wid * 0.5, len * 0.28, -wid * 0.2);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
      ctx.restore();
    }
  }

  // tail
  if (p.tail > 0 && p.tailType !== 'none') {
    const sway = Math.sin(walk * 0.9 + phase) * (moving ? 0.22 : 0.09);
    ctx.save();
    ctx.translate(-len * 0.42, 0);
    ctx.rotate(sway);
    if (p.tailType === 'whip' || p.tailType === 'spike') {
      ctx.strokeStyle = p.color2;
      ctx.lineWidth = Math.max(2.4, wid * 0.16);
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(-p.tail * 0.55, 0, -p.tail, p.tail * 0.1);
      ctx.stroke();
      if (p.tailType === 'spike') {
        ctx.fillStyle = p.color3;
        for (let i = 0; i < 3; i++) {
          const t = 0.35 + i * 0.2;
          ctx.beginPath();
          ctx.moveTo(-p.tail * t, 0);
          ctx.lineTo(-p.tail * (t + 0.08), -3 - i);
          ctx.lineTo(-p.tail * (t + 0.12), 0);
          ctx.closePath();
          ctx.fill();
        }
      }
    } else if (p.tailType === 'fin') {
      ctx.fillStyle = rgba(p.color3, 0.55);
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(-p.tail * 0.6, -p.tail * 0.55, -p.tail, 0);
      ctx.quadraticCurveTo(-p.tail * 0.6, p.tail * 0.55, 0, 0);
      ctx.fill();
    } else if (p.tailType === 'puff' || p.tailType === 'tuft') {
      ctx.fillStyle = p.color3;
      ctx.beginPath();
      ctx.ellipse(-p.tail * 0.7, 0, p.tail * 0.36, p.tail * 0.28, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = p.color2;
      ctx.beginPath();
      ctx.ellipse(-p.tail * 0.55, 0, p.tail * 0.24, p.tail * 0.2, 0, 0, Math.PI * 2);
      ctx.fill();
    } else {
      ctx.fillStyle = p.color2;
      ctx.beginPath();
      ctx.moveTo(0, -wid * 0.16);
      ctx.quadraticCurveTo(-p.tail * 0.7, -wid * 0.24, -p.tail, 0);
      ctx.quadraticCurveTo(-p.tail * 0.7, wid * 0.24, 0, wid * 0.16);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  }

  // legs
  if (p.legs > 0 && legLen > 0) {
    const pairs = Math.ceil(p.legs / 2);
    for (let i = 0; i < pairs; i++) {
      const side = i / 2 + 0.5;
      const lx = -len * 0.3 + (i / Math.max(1, pairs - 1)) * len * 0.6;
      for (const s of [-1, 1]) {
        const swing = Math.sin(walk + i * 1.7 + (s > 0 ? Math.PI : 0)) * (moving ? 0.55 : 0.15);
        const hipX = lx;
        const hipY = s * wid * 0.34;
        const footX = hipX + Math.sin(swing) * legLen * 0.55;
        const footY = hipY + s * legLen * (0.64 + Math.abs(Math.cos(swing)) * 0.2);
        ctx.strokeStyle = p.color2;
        ctx.lineWidth = Math.max(2, wid * 0.13);
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(hipX, hipY);
        ctx.quadraticCurveTo(hipX + footX * 0.15, hipY + s * legLen * 0.55, footX, footY);
        ctx.stroke();
        ctx.fillStyle = p.color3;
        ctx.beginPath();
        ctx.arc(footX, footY, Math.max(1.3, wid * 0.075), 0, Math.PI * 2);
        ctx.fill();
        if (p.claws > 0) {
          ctx.strokeStyle = '#f1ead8';
          ctx.lineWidth = 0.9;
          for (let c = -1; c <= 1; c++) {
            ctx.beginPath();
            ctx.moveTo(footX + c * 2.1, footY + s * 1.2);
            ctx.lineTo(footX + c * 2.8, footY + s * 4 + (c === 0 ? 1 : 0));
            ctx.stroke();
          }
        }
      }
    }
  }

  // dorsal fin
  if (p.fin || p.tailType === 'fin') {
    ctx.fillStyle = rgba(p.color3, 0.5);
    ctx.beginPath();
    ctx.moveTo(-len * 0.15, -wid * 0.44);
    ctx.quadraticCurveTo(-len * 0.02, -wid * 0.95, len * 0.18, -wid * 0.44);
    ctx.closePath();
    ctx.fill();
  }

  // side spikes
  if (p.spikes > 0) {
    ctx.fillStyle = p.color3;
    for (let i = 0; i < p.spikes; i++) {
      const t = (i + 0.5) / p.spikes;
      const sx = -len * 0.28 + t * len * 0.58;
      const s = i % 2 === 0 ? -1 : 1;
      const sh = wid * (0.38 + (i % 3) * 0.08);
      ctx.beginPath();
      ctx.moveTo(sx - 3, s * wid * 0.35);
      ctx.lineTo(sx, s * (wid * 0.5 + sh));
      ctx.lineTo(sx + 4, s * wid * 0.36);
      ctx.closePath();
      ctx.fill();
    }
  }

  // body
  const grad = ctx.createRadialGradient(-len * 0.12, -wid * 0.24, wid * 0.1, 0, 0, len * 0.6);
  grad.addColorStop(0, p.color3);
  grad.addColorStop(0.42, p.color1);
  grad.addColorStop(1, p.color2);
  ctx.fillStyle = grad;
  bodyPath(ctx, len, wid);
  ctx.fill();

  // patterns clipped to body
  ctx.save();
  bodyPath(ctx, len, wid);
  ctx.clip();
  ctx.fillStyle = rgba(p.patternColor, 0.62);
  if (p.pattern === 'spots') {
    for (let i = 0; i < 9; i++) {
      const a = (i / 9) * Math.PI * 2 + (p.scale || 1);
      const rr = 0.18 + ((i * 37) % 24) / 100;
      ctx.beginPath();
      ctx.arc(Math.cos(a) * len * rr * 0.7, Math.sin(a) * wid * rr * 0.64, wid * (0.055 + (i % 3) * 0.02), 0, Math.PI * 2);
      ctx.fill();
    }
  } else if (p.pattern === 'stripes') {
    for (let i = -2; i <= 2; i++) {
      ctx.save();
      ctx.translate(i * len * 0.13, 0);
      ctx.rotate(0.28);
      ctx.fillRect(-len * 0.022, -wid, len * 0.052, wid * 2);
      ctx.restore();
    }
  }
  ctx.restore();

  // carapace plates
  if (p.armor > 0) {
    ctx.strokeStyle = rgba('#f2ead6', 0.35);
    ctx.lineWidth = 1.2;
    for (let i = 0; i < 3 + p.armor; i++) {
      const px = -len * 0.25 + (i / (2 + p.armor)) * len * 0.55;
      ctx.beginPath();
      ctx.ellipse(px, 0, len * 0.06, wid * 0.39, 0, -Math.PI * 0.45, Math.PI * 0.45);
      ctx.stroke();
    }
    ctx.fillStyle = rgba('#f2ead6', 0.22);
    ctx.beginPath();
    ctx.ellipse(-len * 0.02, -wid * 0.12, len * 0.28, wid * 0.16, 0, 0, Math.PI * 2);
    ctx.fill();
  }

  // rim light
  ctx.strokeStyle = rgba('#ffffff', 0.14);
  ctx.lineWidth = 1.2;
  bodyPath(ctx, len, wid);
  ctx.stroke();

  // head
  const hx = len * 0.43;
  const hg = ctx.createRadialGradient(hx - head * 0.18, -head * 0.28, 1, hx, 0, head * 1.2);
  hg.addColorStop(0, p.color3);
  hg.addColorStop(0.5, p.color1);
  hg.addColorStop(1, p.color2);
  ctx.fillStyle = hg;
  ctx.beginPath();
  ctx.ellipse(hx + head * 0.1, 0, head * 0.66, head * 0.58, 0, 0, Math.PI * 2);
  ctx.fill();

  // snout
  ctx.fillStyle = p.color1;
  ctx.beginPath();
  ctx.ellipse(hx + head * 0.72, 0, head * 0.3, head * 0.24, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = rgba(p.color2, 0.9);
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(hx + head * 0.78, 0, head * 0.2, -0.8, 0.8);
  ctx.stroke();
  if (p.teeth) {
    ctx.fillStyle = '#f7f0dd';
    for (let i = 0; i < 3; i++) {
      const tx = hx + head * 0.7 + i * 2.1;
      ctx.beginPath();
      ctx.moveTo(tx, head * 0.13);
      ctx.lineTo(tx + 1.4, head * 0.13);
      ctx.lineTo(tx + 0.6, head * 0.25);
      ctx.closePath();
      ctx.fill();
    }
  }

  // ears
  if (p.ears > 0) {
    ctx.fillStyle = p.color2;
    for (const s of [-1, 1]) {
      ctx.beginPath();
      ctx.ellipse(hx - head * 0.18, s * head * 0.42, head * 0.2, head * 0.11, s * 0.65, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = p.color3;
      ctx.beginPath();
      ctx.ellipse(hx - head * 0.18, s * head * 0.42, head * 0.11, head * 0.06, s * 0.65, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = p.color2;
    }
  }

  // horns
  if (p.horns > 0) {
    ctx.fillStyle = '#e9dfc6';
    ctx.strokeStyle = 'rgba(80,60,40,.35)';
    ctx.lineWidth = 0.8;
    for (let i = 0; i < p.horns; i++) {
      const s = i % 2 === 0 ? -1 : 1;
      const hlen = head * (0.7 + (i % 3) * 0.15);
      ctx.beginPath();
      ctx.moveTo(hx + head * 0.18, s * head * 0.3);
      ctx.quadraticCurveTo(hx + head * 0.55, s * head * 0.66, hx + head * 0.45, s * (head * 0.3 + hlen));
      ctx.quadraticCurveTo(hx + head * 0.32, s * head * 0.55, hx + head * 0.05, s * head * 0.2);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
    }
  }

  // eyes
  const eyeCount = Math.min(3, p.eyes || 2);
  for (let i = 0; i < eyeCount; i++) {
    const s = eyeCount === 1 ? 0 : i === 0 ? -1 : 1;
    const ex = hx + head * 0.28 + (i === 2 ? -head * 0.22 : 0);
    const ey = s * head * 0.27;
    if (p.glow) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      ctx.fillStyle = rgba(p.glow, 0.22);
      ctx.beginPath();
      ctx.arc(ex, ey, head * 0.34, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
    ctx.fillStyle = p.eye;
    ctx.beginPath();
    ctx.ellipse(ex, ey, head * 0.16, head * 0.13, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = p.pupil;
    ctx.beginPath();
    ctx.ellipse(ex + head * 0.035, ey, head * 0.06, head * 0.1, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.85)';
    ctx.beginPath();
    ctx.arc(ex - head * 0.04, ey - head * 0.04, head * 0.035, 0, Math.PI * 2);
    ctx.fill();
  }

  // bioluminescent dots
  if (p.glow) {
    ctx.fillStyle = rgba(p.glow, 0.8);
    for (let i = 0; i < 5; i++) {
      const t = i / 5;
      ctx.beginPath();
      ctx.arc(-len * 0.22 + t * len * 0.4, (i % 2 ? 1 : -1) * wid * 0.18, 1.4, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  if (opts.flash) {
    ctx.globalAlpha = clamp(opts.flash, 0, 0.75);
    ctx.fillStyle = '#fff4e0';
    bodyPath(ctx, len, wid);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(hx + head * 0.1, 0, head * 0.66, head * 0.58, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1;
  }

  ctx.restore();
}

export function drawCreaturePreview(canvas, pheno, time = 0) {
  const ctx = canvas.getContext('2d');
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  const w = canvas.clientWidth || canvas.width;
  const h = canvas.clientHeight || canvas.height;
  if (canvas.width !== Math.round(w * dpr) || canvas.height !== Math.round(h * dpr)) {
    canvas.width = Math.round(w * dpr);
    canvas.height = Math.round(h * dpr);
  }
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, w, h);
  const g = ctx.createRadialGradient(w / 2, h / 2, 10, w / 2, h / 2, h * 0.8);
  g.addColorStop(0, 'rgba(90,190,140,.15)');
  g.addColorStop(1, 'rgba(90,190,140,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);
  const maxDim = Math.max(pheno.len, pheno.wid);
  const scale = Math.min(1.6, (h * 0.62) / maxDim);
  ctx.save();
  ctx.translate(w / 2, h / 2 + 6);
  ctx.scale(scale, scale);
  ctx.translate(-pheno.len * 0.06, 0);
  drawCreature(ctx, 0, 0, -Math.PI / 2, pheno, time, { moving: false, selected: false });
  ctx.restore();
}

:root {
  --bg: #06110d;
  --panel: rgba(10, 25, 19, 0.84);
  --panel-solid: #0a1a14;
  --line: rgba(141, 240, 183, 0.16);
  --line-bright: rgba(141, 240, 183, 0.34);
  --green: #7cf0a8;
  --green-dim: #3c9b68;
  --gold: #ffd479;
  --pink: #ff9ec7;
  --blue: #79c9ff;
  --purple: #b58cff;
  --red: #ff6b7a;
  --ink: #eaf7ef;
  --muted: #9bb3a6;
  --shadow: 0 18px 50px rgba(0, 0, 0, 0.42);
  --r: 16px;
  --safe-bottom: env(safe-area-inset-bottom, 0px);
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--ink);
  font-family: "Avenir Next", "Segoe UI", "Trebuchet MS", system-ui, sans-serif;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}
button { font-family: inherit; color: inherit; cursor: pointer; }
button:focus-visible { outline: 2px solid var(--green); outline-offset: 2px; }
.hidden { display: none !important; }

#app { position: fixed; inset: 0; }
#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: crosshair;
}

.hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 5;
}
.hud > *, .hud-left > *, .hud-right > * { pointer-events: none; }
.hud button, .hud canvas { pointer-events: auto; }

.card {
  background: linear-gradient(155deg, rgba(16, 36, 27, 0.88), rgba(8, 20, 15, 0.82));
  border: 1px solid var(--line);
  border-radius: var(--r);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.hud-left {
  position: absolute;
  top: 16px;
  left: 16px;
  width: 300px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.profile {
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 10px 14px 10px 10px;
}
.avatar-wrap {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  overflow: hidden;
  flex: none;
  background: radial-gradient(circle at 50% 40%, #25553e, #0a1a14 70%);
  border: 1px solid var(--line-bright);
  box-shadow: inset 0 0 18px rgba(124, 240, 168, 0.12);
}
#avatar { width: 100%; height: 100%; display: block; }
.pinfo { flex: 1; min-width: 0; }
.pname { display: flex; align-items: center; gap: 8px; font-size: 17px; font-weight: 700; letter-spacing: 0.3px; }
.gen {
  font-size: 9px;
  letter-spacing: 1.2px;
  color: var(--gold);
  border: 1px solid rgba(255, 212, 121, 0.34);
  padding: 2px 5px;
  border-radius: 5px;
  background: rgba(255, 212, 121, 0.08);
}
.stage-name { font-size: 11px; letter-spacing: 1.6px; text-transform: uppercase; color: var(--green); margin-top: 1px; }
.xpbar { height: 5px; background: rgba(255,255,255,0.08); border-radius: 4px; margin-top: 7px; overflow: hidden; }
.xpbar i { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, var(--green-dim), var(--green)); border-radius: 4px; transition: width 0.4s ease; }
.xp-label { display: flex; justify-content: space-between; font-size: 9px; color: var(--muted); margin-top: 3px; letter-spacing: 0.5px; }

.vitals { padding: 9px 12px; display: flex; flex-direction: column; gap: 6px; }
.bar { display: flex; align-items: center; gap: 8px; font-size: 10px; color: var(--muted); }
.bar .ico { width: 13px; text-align: center; font-size: 11px; filter: saturate(1.2); }
.bar .track { flex: 1; height: 7px; background: rgba(0,0,0,0.35); border-radius: 5px; overflow: hidden; box-shadow: inset 0 1px 2px rgba(0,0,0,0.4); }
.bar .track i { display: block; height: 100%; width: 100%; border-radius: 5px; transition: width 0.25s ease, background 0.3s; }
.bar b { width: 30px; text-align: right; font-weight: 600; font-size: 9px; color: #cfe6d8; font-variant-numeric: tabular-nums; }
.bar.hp i { background: linear-gradient(90deg, #a52f45, #ff6b7a); }
.bar.stamina i { background: linear-gradient(90deg, #96701f, #ffd479); }
.bar.food i { background: linear-gradient(90deg, #8b4d2e, #f0a06c); }
.bar.water i { background: linear-gradient(90deg, #2c6b8c, #79c9ff); }
.bar.low i { animation: lowPulse 0.9s infinite alternate; }
@keyframes lowPulse { from { filter: brightness(0.8); } to { filter: brightness(1.5); } }

.lineage { display: flex; align-items: center; gap: 10px; padding: 7px 12px; font-size: 10px; color: var(--muted); }
.lineage b { color: var(--gold); }
.lineage-bonus { color: var(--green); }
.heir-count { margin-left: auto; }

.hud-right { position: absolute; top: 16px; right: 16px; width: 196px; display: flex; flex-direction: column; gap: 8px; }
.mapcard { padding: 7px; position: relative; overflow: hidden; }
#minimap {
  width: 100%;
  height: auto;
  aspect-ratio: 1;
  display: block;
  border-radius: 11px;
  background: #071712;
  border: 1px solid rgba(141, 240, 183, 0.1);
  image-rendering: auto;
}
.maptop, .mapbottom {
  position: absolute;
  left: 12px;
  right: 12px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 8px;
  letter-spacing: 0.9px;
  text-transform: uppercase;
  pointer-events: none;
}
.maptop { top: 12px; color: #d9efe2; text-shadow: 0 1px 4px #000; }
.mapbottom { bottom: 12px; color: #b8d6c5; text-shadow: 0 1px 4px #000; }
#clock { color: var(--gold); font-weight: 700; font-size: 9px; }
.dna { display: flex; align-items: center; gap: 7px; padding: 8px 10px; }
.dna-icon { font-size: 16px; filter: drop-shadow(0 0 6px rgba(255,158,199,.5)); }
.dna b { font-size: 19px; color: var(--pink); font-variant-numeric: tabular-nums; text-shadow: 0 0 18px rgba(255,158,199,.35); }
.dna-label { font-size: 8px; letter-spacing: 1.5px; color: var(--muted); }
.dna .mini {
  margin-left: auto;
  font-size: 9px;
  padding: 6px 8px;
  border-radius: 8px;
  border: 1px solid var(--line-bright);
  background: rgba(124, 240, 168, 0.1);
  color: var(--green);
  letter-spacing: 0.6px;
  text-transform: uppercase;
}
.dna .mini kbd { font-size: 8px; opacity: 0.6; margin-left: 2px; }

.quest {
  position: absolute;
  left: 16px;
  bottom: 18px;
  width: 274px;
  padding: 11px 14px 12px;
  border-left: 2px solid var(--green);
}
.qtop { display: flex; justify-content: space-between; font-size: 8px; letter-spacing: 1.8px; color: var(--green); }
#quest-count { color: var(--muted); }
#quest-title { font-size: 14px; font-weight: 700; margin: 4px 0 3px; }
#quest-text { font-size: 10px; line-height: 1.45; color: var(--muted); }
.qprog { height: 3px; border-radius: 3px; background: rgba(255,255,255,.08); margin-top: 8px; overflow: hidden; }
.qprog i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, var(--green-dim), var(--green)); transition: width 0.4s; }
.qhint { font-size: 9px; color: rgba(255, 212, 121, 0.85); margin-top: 6px; line-height: 1.4; }

.prompt {
  position: absolute;
  left: 50%;
  bottom: 88px;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 9px;
  background: rgba(7, 18, 14, 0.9);
  border: 1px solid var(--line-bright);
  border-radius: 999px;
  padding: 8px 16px 8px 9px;
  font-size: 12px;
  box-shadow: 0 12px 30px rgba(0,0,0,.35), 0 0 24px rgba(124,240,168,.08);
  white-space: nowrap;
  max-width: calc(100vw - 30px);
  overflow: hidden;
  text-overflow: ellipsis;
}
.prompt .key {
  font-size: 11px;
  font-weight: 800;
  color: #08130e;
  background: var(--green);
  border-radius: 50%;
  width: 24px;
  height: 24px;
  display: grid;
  place-items: center;
  flex: none;
}
.prompt.alt .key { background: var(--gold); }

.hotbar {
  position: absolute;
  bottom: 18px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 6px;
}
.slot {
  min-width: 76px;
  padding: 7px 9px 6px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(8, 20, 15, 0.78);
  backdrop-filter: blur(6px);
  text-align: center;
  position: relative;
  overflow: hidden;
}
.slot kbd { display: block; font-size: 8px; letter-spacing: 1px; color: var(--green); margin-bottom: 2px; }
.slot span { font-size: 10px; color: var(--muted); }
.slot.ability { border-color: rgba(181, 140, 255, 0.32); }
.slot.ability kbd { color: var(--purple); }
.slot .cd {
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,0.6);
  transform-origin: bottom;
  transform: scaleY(0);
  pointer-events: none;
}

.menubtns {
  position: absolute;
  top: 16px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 6px;
  background: rgba(7, 18, 14, 0.62);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 5px;
  backdrop-filter: blur(8px);
}
.menubtns button {
  width: 45px;
  height: 38px;
  border-radius: 8px;
  border: 1px solid transparent;
  background: transparent;
  font-size: 16px;
  line-height: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  color: #cfe6d8;
  transition: 0.15s;
}
.menubtns button:hover { background: rgba(124, 240, 168, 0.1); border-color: var(--line); }
.menubtns kbd { font-size: 6px; letter-spacing: 0.5px; color: var(--muted); }
.menubtns button:active { transform: translateY(1px); }

.toasts {
  position: absolute;
  top: 74px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  width: max-content;
  max-width: min(460px, 90vw);
  z-index: 8;
}
.toast {
  background: linear-gradient(150deg, rgba(14, 33, 24, 0.96), rgba(8, 19, 14, 0.94));
  border: 1px solid var(--line-bright);
  border-left: 3px solid var(--green);
  border-radius: 10px;
  padding: 8px 14px;
  font-size: 11px;
  line-height: 1.4;
  text-align: center;
  box-shadow: var(--shadow);
  animation: toastIn 0.35s cubic-bezier(.2,.9,.3,1.2);
  color: #dcf3e6;
}
.toast.gold { border-left-color: var(--gold); color: #fff2cc; }
.toast.pink { border-left-color: var(--pink); color: #ffe0ed; }
.toast.purple { border-left-color: var(--purple); color: #eee2ff; }
.toast.red { border-left-color: var(--red); color: #ffdede; }
.toast.leaving { animation: toastOut 0.4s forwards; }
@keyframes toastIn { from { opacity: 0; transform: translateY(-8px) scale(.96); } to { opacity: 1; } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-6px) scale(.97); } }

.low-health {
  position: absolute;
  inset: 0;
  pointer-events: none;
  box-shadow: inset 0 0 160px rgba(190, 20, 44, 0.55);
  opacity: 0;
  transition: opacity 0.4s;
  z-index: 4;
}

.mobile-controls { display: none; }

/* ---------- Modal panels ---------- */
.modal {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 22px;
  background: rgba(2, 8, 5, 0.72);
  backdrop-filter: blur(9px);
  -webkit-backdrop-filter: blur(9px);
  animation: fadeIn 0.2s ease;
}
@keyframes fadeIn { from { opacity: 0; } }
.panel {
  width: min(1020px, 100%);
  max-height: min(88vh, 900px);
  background:
    radial-gradient(120% 80% at 50% 0%, rgba(38, 82, 59, 0.36), transparent 60%),
    linear-gradient(160deg, #0d2118, #08150f 70%);
  border: 1px solid rgba(141, 240, 183, 0.22);
  border-radius: 22px;
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.66), inset 0 1px 0 rgba(255,255,255,.06);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: panelIn 0.28s cubic-bezier(.2,.9,.3,1.05);
}
@keyframes panelIn { from { opacity: 0; transform: translateY(14px) scale(.985); } }
.panel-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 20px 24px 14px;
  border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(30, 66, 48, 0.24), transparent);
}
.panel-head h2 {
  margin: 0;
  font-size: 25px;
  letter-spacing: 0.6px;
  font-weight: 800;
  background: linear-gradient(100deg, #dffbea, #7cf0a8 68%, #ffd479);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.panel-head p { margin: 4px 0 0; color: var(--muted); font-size: 11px; letter-spacing: 0.3px; }
#panel-close {
  border: 1px solid var(--line);
  background: rgba(255,255,255,0.04);
  width: 36px;
  height: 36px;
  border-radius: 50%;
  color: var(--muted);
  font-size: 14px;
  flex: none;
  transition: 0.15s;
}
#panel-close:hover { background: rgba(255,107,122,.14); color: #ffd8dc; border-color: rgba(255,107,122,.35); }
.panel-body { padding: 18px 24px 24px; overflow-y: auto; overscroll-behavior: contain; }

.eyebrow { font-size: 9px; letter-spacing: 3px; text-transform: uppercase; color: var(--green); font-weight: 700; }

/* mutation panel */
.mut-hero { display: grid; grid-template-columns: 290px 1fr; gap: 16px; margin-bottom: 16px; }
.preview-card {
  border: 1px solid var(--line);
  border-radius: 16px;
  background: radial-gradient(circle at 50% 42%, rgba(60, 140, 95, 0.2), rgba(6, 16, 11, 0.5));
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
#preview-canvas { width: 100%; height: 150px; display: block; border-radius: 10px; }
.preview-name { display: flex; justify-content: space-between; align-items: baseline; padding: 0 4px; }
.preview-name b { font-size: 14px; }
.preview-name span { font-size: 9px; color: var(--green); letter-spacing: 1px; text-transform: uppercase; }
.stat-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
}
.stat {
  border: 1px solid rgba(255,255,255,.05);
  background: rgba(0,0,0,.18);
  border-radius: 9px;
  padding: 6px 7px;
}
.stat span { display: block; font-size: 7px; letter-spacing: 1px; color: var(--muted); text-transform: uppercase; }
.stat b { font-size: 13px; color: #dffbea; font-variant-numeric: tabular-nums; }
.stat i { display: block; height: 2px; background: var(--green); margin-top: 4px; border-radius: 2px; opacity: .55; width: var(--w, 50%); }
.mut-summary {
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  background: linear-gradient(150deg, rgba(30, 66, 48, 0.2), rgba(0,0,0,.1));
}
.mut-summary h3 { margin: 0; font-size: 13px; letter-spacing: .5px; }
.mut-summary p { margin: 0; font-size: 10px; color: var(--muted); line-height: 1.55; }
.dna-big { font-size: 30px; color: var(--pink); font-weight: 800; line-height: 1; }
.dna-big small { font-size: 10px; letter-spacing: 1.4px; color: var(--muted); font-weight: 600; margin-left: 5px; }
.cat-tabs { display: flex; gap: 6px; flex-wrap: wrap; margin: 6px 0 12px; }
.cat-tabs button {
  border: 1px solid var(--line);
  background: rgba(255,255,255,.03);
  color: var(--muted);
  padding: 7px 13px;
  border-radius: 999px;
  font-size: 10px;
  letter-spacing: .6px;
}
.cat-tabs button.active { color: #07130f; background: var(--green); border-color: var(--green); font-weight: 800; }
.gene-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(238px, 1fr)); gap: 9px; }
.gene-card {
  text-align: left;
  border: 1px solid var(--line);
  background: linear-gradient(160deg, rgba(20, 44, 32, 0.62), rgba(7, 18, 13, 0.58));
  border-radius: 13px;
  padding: 11px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  transition: 0.16s;
  position: relative;
  overflow: hidden;
}
.gene-card:hover { border-color: var(--line-bright); transform: translateY(-1px); background: linear-gradient(160deg, rgba(28, 60, 43, 0.76), rgba(8, 20, 15, 0.66)); }
.gene-card.can-buy { border-color: rgba(124, 240, 168, 0.42); box-shadow: 0 0 0 1px rgba(124,240,168,.08), 0 8px 24px rgba(0,0,0,.2); }
.gene-card.maxed { opacity: .78; }
.gene-card.locked { opacity: .52; filter: saturate(.6); cursor: not-allowed; }
.gene-card.broke { opacity: .68; }
.gene-card.bought { animation: boughtFlash 0.5s; }
@keyframes boughtFlash { 0% { box-shadow: 0 0 0 2px var(--green), 0 0 38px rgba(124,240,168,.55); } }
.g-head { display: flex; align-items: center; gap: 8px; }
.g-icon {
  width: 30px;
  height: 30px;
  border-radius: 9px;
  display: grid;
  place-items: center;
  background: color-mix(in srgb, var(--c, #7cf0a8) 14%, transparent);
  border: 1px solid color-mix(in srgb, var(--c, #7cf0a8) 32%, transparent);
  color: var(--c, #7cf0a8);
  font-size: 14px;
  flex: none;
}
.g-head .g-title { flex: 1; min-width: 0; }
.g-head h3 { margin: 0; font-size: 13px; letter-spacing: .2px; }
.g-head .cat { font-size: 7.5px; letter-spacing: 1.4px; text-transform: uppercase; color: var(--muted); }
.g-rank { font-size: 9px; color: var(--gold); border: 1px solid rgba(255,212,121,.25); border-radius: 5px; padding: 2px 5px; flex: none; }
.g-blurb { margin: 0; font-size: 9.5px; color: var(--muted); line-height: 1.4; min-height: 26px; }
.g-pips { display: flex; gap: 3px; }
.g-pips i { height: 4px; flex: 1; border-radius: 3px; background: rgba(255,255,255,.1); }
.g-pips i.on { background: var(--c, var(--green)); box-shadow: 0 0 7px color-mix(in srgb, var(--c, #7cf0a8) 45%, transparent); }
.g-foot { display: flex; align-items: flex-end; justify-content: space-between; gap: 8px; }
.g-effect { font-size: 9px; color: #bfe9d0; line-height: 1.35; }
.g-cost { font-size: 10px; font-weight: 800; color: var(--pink); white-space: nowrap; display: flex; align-items: center; gap: 3px; }
.g-cost.locked-label { color: var(--muted); font-weight: 600; }
.g-cost.max-label { color: var(--gold); }

/* build panel */
.mat-row { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 14px; }
.mat {
  display: flex;
  align-items: center;
  gap: 6px;
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 7px 11px;
  background: rgba(0,0,0,.18);
  font-size: 11px;
}
.mat b { font-variant-numeric: tabular-nums; color: #eaf7ef; }
.mat span { color: var(--muted); font-size: 9px; letter-spacing: .8px; text-transform: uppercase; }
.mat.short b { color: var(--red); }
.den-banner {
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 14px 16px;
  background: linear-gradient(120deg, rgba(255, 212, 121, .07), rgba(0,0,0,.16));
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 14px;
}
.den-banner .big-icon { font-size: 30px; }
.den-banner h3 { margin: 0 0 3px; font-size: 15px; }
.den-banner p { margin: 0; font-size: 10px; color: var(--muted); line-height: 1.45; }
.den-banner .spacer { flex: 1; }
.panel-btn {
  border: 1px solid var(--line-bright);
  background: rgba(124, 240, 168, 0.1);
  color: var(--green);
  border-radius: 9px;
  padding: 9px 14px;
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}
.panel-btn:hover { background: rgba(124, 240, 168, 0.18); }
.panel-btn.primary { background: var(--green); color: #07130f; border-color: var(--green); }
.panel-btn.gold { background: linear-gradient(120deg, #ffd479, #f0a94e); color: #241605; border-color: #ffd479; }
.panel-btn.pink { background: linear-gradient(120deg, #ff9ec7, #e26b9e); color: #2a0a18; border-color: #ff9ec7; }
.panel-btn:disabled { opacity: .4; cursor: not-allowed; filter: grayscale(.4); }
.panel-btn.danger { color: var(--red); border-color: rgba(255,107,122,.4); background: rgba(255,107,122,.08); }
.module-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 9px; }
.module-card {
  border: 1px solid var(--line);
  border-radius: 13px;
  padding: 12px;
  background: rgba(0,0,0,.17);
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.module-card.built { border-color: rgba(124,240,168,.32); background: linear-gradient(150deg, rgba(42, 92, 62, .24), rgba(0,0,0,.17)); }
.module-card.maxed { border-color: rgba(255,212,121,.28); }
.mc-head { display: flex; align-items: center; gap: 8px; }
.mc-head .mic { font-size: 20px; }
.mc-head h3 { margin: 0; font-size: 13px; flex: 1; }
.mc-head .rank { font-size: 9px; color: var(--gold); }
.module-card p { margin: 0; font-size: 9.5px; color: var(--muted); line-height: 1.45; }
.module-card .effect { font-size: 9px; color: #bfe9d0; }
.mc-foot { display: flex; align-items: center; gap: 8px; margin-top: 2px; }
.mc-cost { font-size: 9px; color: var(--muted); flex: 1; }
.mc-cost b { color: #eaf7ef; }
.mc-cost.short b { color: var(--red); }

/* breeding */
.breed-layout { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.mate-card, .heir-card {
  border: 1px solid var(--line);
  border-radius: 15px;
  padding: 15px;
  background: radial-gradient(circle at 50% 0%, rgba(255,158,199,.08), rgba(0,0,0,.16));
  display: flex;
  flex-direction: column;
  gap: 9px;
}
.mate-card h3, .heir-card h3 { margin: 0; font-size: 15px; }
.affinity { height: 7px; background: rgba(0,0,0,.4); border-radius: 5px; overflow: hidden; }
.affinity i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, #a94d76, #ff9ec7); transition: width .4s; }
.mate-meta { display: flex; justify-content: space-between; font-size: 9px; color: var(--muted); }
.genome-list { display: flex; flex-wrap: wrap; gap: 4px; }
.gene-chip {
  font-size: 8.5px;
  border: 1px solid rgba(181,140,255,.26);
  background: rgba(181,140,255,.08);
  color: #ddc9ff;
  border-radius: 999px;
  padding: 3px 7px;
  white-space: nowrap;
}
.gene-chip.player { border-color: rgba(124,240,168,.26); background: rgba(124,240,168,.08); color: #c9f7db; }
.gene-chip.up { border-color: rgba(255,212,121,.5); background: rgba(255,212,121,.14); color: #ffe9b5; }
.breed-actions { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 6px; }
.breed-note { font-size: 9.5px; color: var(--muted); line-height: 1.5; }
.empty-state { border: 1px dashed var(--line); border-radius: 14px; padding: 28px 20px; text-align: center; color: var(--muted); font-size: 11px; line-height: 1.6; }
.empty-state b { color: var(--ink); display: block; font-size: 14px; margin-bottom: 4px; }

/* journal */
.journal-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.jcard { border: 1px solid var(--line); border-radius: 14px; padding: 14px; background: rgba(0,0,0,.15); }
.jcard h3 { margin: 0 0 9px; font-size: 11px; letter-spacing: 1.6px; text-transform: uppercase; color: var(--green); }
.jcard.wide { grid-column: 1 / -1; }
.stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.stats-grid .stat b { font-size: 15px; }
.stats-grid .stat span { font-size: 7px; }
.disc-grid { display: flex; flex-wrap: wrap; gap: 5px; }
.disc { font-size: 9px; border: 1px solid var(--line); border-radius: 999px; padding: 4px 8px; color: var(--muted); }
.disc.found { color: #dffbea; border-color: rgba(124,240,168,.3); background: rgba(124,240,168,.07); }
.ach-list { display: flex; flex-direction: column; gap: 5px; }
.ach { display: flex; gap: 8px; align-items: center; font-size: 9.5px; color: var(--muted); }
.ach .dot { width: 7px; height: 7px; border-radius: 50%; background: rgba(255,255,255,.12); flex: none; }
.ach.done { color: #dffbea; }
.ach.done .dot { background: var(--gold); box-shadow: 0 0 8px rgba(255,212,121,.5); }
.ach b { font-size: 10px; }
.controls-list { display: grid; grid-template-columns: 1fr 1fr; gap: 4px 14px; font-size: 9.5px; color: var(--muted); }
.controls-list b { color: var(--ink); font-size: 9px; }
.setting-row { display: flex; align-items: center; gap: 8px; margin-top: 10px; font-size: 10px; color: var(--muted); }
.setting-row input[type=range] { flex: 1; accent-color: var(--green); }
.setting-row .swatch { width: 20px; height: 20px; border-radius: 50%; border: 1px solid var(--line-bright); }
.lineage-list { display: flex; flex-direction: column; gap: 6px; font-size: 10px; color: var(--muted); }
.lineage-list .heir { border-left: 2px solid var(--gold); padding-left: 8px; }
.lineage-list b { color: var(--ink); }

/* map panel */
.map-wrap { position: relative; border: 1px solid var(--line); border-radius: 16px; overflow: hidden; background: #061611; }
#bigmap { width: 100%; height: auto; display: block; aspect-ratio: 1 / 0.82; }
.map-legend { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 12px; }
.leg { display: flex; align-items: center; gap: 5px; font-size: 9px; color: var(--muted); }
.leg i { width: 9px; height: 9px; border-radius: 3px; display: block; }
.map-stats { display: flex; gap: 14px; flex-wrap: wrap; margin-top: 10px; font-size: 10px; color: var(--muted); }
.map-stats b { color: var(--ink); }

/* pause */
.pause-grid { display: flex; flex-direction: column; gap: 8px; max-width: 380px; margin: 0 auto; }
.pause-grid .panel-btn { width: 100%; padding: 13px; font-size: 12px; }
.pause-note { text-align: center; color: var(--muted); font-size: 9.5px; margin-top: 14px; }

/* title & death overlays */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(90% 90% at 22% 50%, rgba(3,11,7,.9), rgba(3,10,7,.35) 62%, rgba(3,10,7,.72));
}
.title { justify-content: flex-start; padding-left: clamp(28px, 7vw, 120px); transition: opacity .5s, visibility .5s; }
.title.hidden { display: flex !important; opacity: 0; visibility: hidden; pointer-events: none; }
.title-inner { max-width: 690px; position: relative; z-index: 2; }
.title h1 {
  margin: 10px 0 12px;
  font-size: clamp(60px, 8.6vw, 126px);
  line-height: .82;
  letter-spacing: -3px;
  font-weight: 900;
  color: #eafff2;
  text-shadow: 0 6px 40px rgba(0,0,0,.5);
}
.title h1 span {
  display: block;
  font-size: .58em;
  letter-spacing: clamp(3px, .8vw, 13px);
  background: linear-gradient(95deg, #7cf0a8 12%, #ffd479 52%, #ff9ec7 92%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  padding-left: 4px;
  filter: drop-shadow(0 0 26px rgba(124,240,168,.24));
}
.title .eyebrow { color: var(--green); }
.lede { color: #c4dccd; font-size: clamp(12px, 1.15vw, 15px); line-height: 1.65; max-width: 540px; margin: 0 0 14px; }
.title-features { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 22px; }
.title-features span {
  font-size: 9px;
  letter-spacing: .5px;
  color: #c7e6d3;
  border: 1px solid rgba(141,240,183,.22);
  border-radius: 999px;
  padding: 5px 10px;
  background: rgba(8, 22, 15, .55);
  backdrop-filter: blur(4px);
}
.title-actions { display: flex; align-items: center; gap: 12px; }
.primary {
  border: none;
  border-radius: 12px;
  padding: 12px 22px;
  background: linear-gradient(135deg, #a8ffc9, #4bd485 60%, #2aa566);
  color: #04150c;
  font-size: 13px;
  font-weight: 900;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  box-shadow: 0 10px 34px rgba(64, 213, 133, .3), inset 0 1px 0 rgba(255,255,255,.4);
  transition: .16s;
}
.primary:hover { transform: translateY(-1px); box-shadow: 0 14px 40px rgba(64,213,133,.42); }
.primary:active { transform: translateY(1px); }
.primary.big { padding: 16px 44px; font-size: 15px; }
.ghost {
  border: 1px solid rgba(141,240,183,.28);
  background: rgba(10, 28, 19, .5);
  color: #d5edde;
  border-radius: 12px;
  padding: 13px 20px;
  font-size: 11px;
  letter-spacing: 1px;
  text-transform: uppercase;
  backdrop-filter: blur(4px);
}
.ghost:hover { border-color: var(--green); color: var(--green); }
.title-foot { margin-top: 24px; font-size: 9px; letter-spacing: 1px; color: rgba(200,225,210,.55); }
.title-credit { position: absolute; bottom: 20px; left: 50%; transform: translateX(-50%); font-size: 8px; letter-spacing: 1.6px; text-transform: uppercase; color: rgba(200,225,210,.32); white-space: nowrap; }
.spores { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
.spores i {
  position: absolute;
  width: 4px; height: 4px;
  border-radius: 50%;
  background: rgba(160, 255, 200, .55);
  box-shadow: 0 0 12px rgba(124, 240, 168, .65);
  animation: drift 14s linear infinite;
  bottom: -10px;
}
.spores i:nth-child(1) { left: 8%; animation-duration: 17s; animation-delay: -2s; }
.spores i:nth-child(2) { left: 18%; animation-duration: 21s; animation-delay: -9s; width: 2px; height: 2px; }
.spores i:nth-child(3) { left: 29%; animation-duration: 13s; animation-delay: -4s; }
.spores i:nth-child(4) { left: 41%; animation-duration: 24s; animation-delay: -13s; width: 3px; height: 3px; }
.spores i:nth-child(5) { left: 56%; animation-duration: 19s; animation-delay: -6s; }
.spores i:nth-child(6) { left: 66%; animation-duration: 15s; animation-delay: -10s; width: 2px; height: 2px; }
.spores i:nth-child(7) { left: 74%; animation-duration: 22s; animation-delay: -1s; }
.spores i:nth-child(8) { left: 82%; animation-duration: 16s; animation-delay: -7s; width: 3px; height: 3px; }
.spores i:nth-child(9) { left: 91%; animation-duration: 20s; animation-delay: -14s; }
.spores i:nth-child(10) { left: 96%; animation-duration: 12s; animation-delay: -3s; width: 2px; height: 2px; }
@keyframes drift {
  0% { transform: translate3d(0, 0, 0) scale(1); opacity: 0; }
  10% { opacity: .8; }
  90% { opacity: .5; }
  100% { transform: translate3d(60px, -105vh, 0) scale(.3); opacity: 0; }
}

.death { background: radial-gradient(circle at 50% 40%, rgba(90, 12, 24, .32), rgba(3, 8, 6, .88)); }
.death-card {
  text-align: center;
  max-width: 440px;
  padding: 36px 34px;
  border: 1px solid rgba(255,107,122,.25);
  border-radius: 22px;
  background: linear-gradient(160deg, rgba(28, 12, 16, .94), rgba(8, 13, 10, .94));
  box-shadow: var(--shadow);
}
.death-card .eyebrow { color: var(--red); }
.death-card h2 { font-size: 38px; margin: 8px 0 6px; letter-spacing: -1px; }
.death-card p { color: var(--muted); font-size: 12px; line-height: 1.6; }
.death-stats { display: flex; justify-content: center; gap: 18px; margin: 18px 0 20px; color: var(--muted); font-size: 9px; letter-spacing: 1px; text-transform: uppercase; }
.death-stats b { display: block; color: var(--ink); font-size: 17px; letter-spacing: 0; }

/* scrollbar */
.panel-body::-webkit-scrollbar { width: 9px; }
.panel-body::-webkit-scrollbar-track { background: rgba(0,0,0,.15); }
.panel-body::-webkit-scrollbar-thumb { background: rgba(124,240,168,.18); border-radius: 8px; }
.panel-body::-webkit-scrollbar-thumb:hover { background: rgba(124,240,168,.3); }

/* ---------- responsive / touch ---------- */
@media (max-width: 860px), (pointer: coarse) {
  .hud-left { top: max(10px, env(safe-area-inset-top)); left: 10px; width: 184px; gap: 5px; }
  .profile { padding: 7px 9px 7px 7px; gap: 8px; border-radius: 13px; }
  .avatar-wrap { width: 42px; height: 42px; }
  .pname { font-size: 13px; gap: 5px; }
  .gen { font-size: 7px; padding: 1px 4px; }
  .stage-name { font-size: 8px; letter-spacing: 1.1px; }
  .xp-label { display: none; }
  .vitals { padding: 7px 9px; gap: 4px; border-radius: 12px; }
  .bar { font-size: 8px; gap: 5px; }
