const DEFAULT = {
  len: 48, wid: 24, head: 16, legLen: 15, legs: 4,
  tail: 20, tailType: 'taper', spikes: 0, horns: 0, ears: 0,
  fin: 0, wing: 0, eyes: 2, pattern: 'spots', patternColor: '#2a4d33',
